window.AD_FOOD = {"countries":[{"i":"AT","dishes":[{"name":"Tafelspitz","desc":"Beef rump simmered slowly in broth with root vegetables and served in its own soup, with an apple-horseradish sauce and a chive cream alongside.","why":"The emperor Franz Joseph is said to have eaten it almost daily; the cut, the broth and the two sauces are all fixed by tradition.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Tafelspitz.jpg/500px-Tafelspitz.jpg"},{"name":"Kaiserschmarrn","desc":"A thick sweet pancake torn into ragged pieces in the pan as it cooks, caramelised with sugar and butter and served with plum compote.","why":"A mountain-hut lunch as much as a dessert; the name means 'the emperor's mess'.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/2015_0731_Kaiserschmarrn_Apfelso%C3%9Fe_Edelweissh%C3%BCtte_S%C3%B6lden.jpg/500px-2015_0731_Kaiserschmarrn_Apfelso%C3%9Fe_Edelweissh%C3%BCtte_S%C3%B6lden.jpg"},{"name":"Sachertorte","desc":"A dense, dryish chocolate sponge split and spread with apricot jam under a hard glossy dark chocolate glaze, served with unsweetened whipped cream.","why":"Created for Prince Metternich's kitchen in 1832; a hotel and a bakery fought a seven-year court case over who could call theirs the original.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Sachertorte_DSC03027.JPG/500px-Sachertorte_DSC03027.JPG"},{"name":"Wiener Schnitzel","desc":"A veal escalope beaten paper-thin, floured, egged and crumbed, then fried in so much fat that the coating puffs away from the meat, served with lemon.","why":"Legally the name applies only to veal; the pork version has to be sold under a different name.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Wiener-Schnitzel02.jpg/500px-Wiener-Schnitzel02.jpg"}]},{"i":"BE","dishes":[{"name":"Waterzooi","desc":"A pale stew of chicken or freshwater fish with julienned root vegetables in a broth enriched at the end with cream and egg yolk.","why":"Ghent's dish; the fish version came first, and moved to chicken as the river's fish stocks collapsed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/%28waterzooi%29_%2879743868%29.jpg/500px-%28waterzooi%29_%2879743868%29.jpg"},{"name":"Carbonnade flamande","desc":"Beef braised slowly in dark ale with onions, a spoon of brown sugar and a slice of mustard-spread bread stirred in at the end to thicken it.","why":"The beer does what wine does further south, and the mustardy bread is the traditional thickener instead of flour."},{"name":"Gaufre de Liège","desc":"A dense, chewy yeasted waffle studded with pearl sugar that melts and caramelises against the hot iron, eaten warm in the hand.","why":"Heavier and sweeter than the light rectangular waffle from Brussels, and sold from vans and street stands rather than plated.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Li%C3%A8ge_waffles_on_a_plate.jpg/500px-Li%C3%A8ge_waffles_on_a_plate.jpg"},{"name":"Moules-frites","desc":"Mussels steamed open in a covered pot with celery, onion and white wine or beer, tipped out with a cone of twice-fried potatoes.","why":"Effectively the national dish; the chips are fried twice, in beef fat, which is the whole argument for where they were invented.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Moules-frites_at_Chez_Leon_in_Brussels.jpg/500px-Moules-frites_at_Chez_Leon_in_Brussels.jpg"}]},{"i":"BR","dishes":[{"name":"Acaraje","desc":"Peeled black-eyed pea batter whipped until airy and deep-fried in red palm oil, then split and stuffed with dried shrimp, cashew paste and hot pepper sauce.","why":"Sold in Salvador by women in white lace; the dish crossed from West Africa and doubles as an offering in Candomble.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Beans_Ball-Akara.jpg/500px-Beans_Ball-Akara.jpg"},{"name":"Moqueca","desc":"A slow stew of fish and prawns cooked in a lidded clay pot with coconut milk, red palm oil, tomato, onion, lime and coriander.","why":"Bahia's version is orange with dende palm oil; Espirito Santo's leaves it out and cooks in a black clay pot made by hand.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Moqueca.jpg/500px-Moqueca.jpg"},{"name":"Coxinha","desc":"A teardrop-shaped croquette of dough enriched with chicken broth, wrapped around shredded chicken and cream cheese, breaded and deep-fried.","why":"Shaped to look like a drumstick -- the name means 'little thigh' -- and sold in every bakery by the counter.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/%282014-11-22%29_La_Donosti_-_Agudos_-_Coxinha_de_Leitoa_Romerito_Pontes_%2815870107515%29.jpg/500px-%282014-11-22%29_La_Donosti_-_Agudos_-_Coxinha_de_Leitoa_Romerito_Pontes_%2815870107515%29.jpg"},{"name":"Pao de queijo","desc":"Small hollow rolls of sour cassava starch and cheese, baked until they puff up, crisp outside and stay chewy and elastic inside.","why":"From Minas Gerais, where cassava starch replaced wheat flour; naturally gluten-free, and eaten hot for breakfast.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Cheesebread.jpg/500px-Cheesebread.jpg"},{"name":"Brigadeiro","desc":"Condensed milk cooked down with cocoa powder and butter until it pulls away from the pan, rolled into balls and coated in chocolate sprinkles.","why":"Named for a 1940s presidential candidate, an air force brigadier whose supporters sold them at campaign events.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Brigadeiro.jpg/330px-Brigadeiro.jpg"},{"name":"Feijoada","desc":"Black beans stewed for hours with salted and smoked pork cuts, served with rice, toasted cassava flour, sauteed collard greens and orange slices.","why":"The Saturday lunch that stops the afternoon; the orange and the greens are there to cut a very heavy pot of pork and beans.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Feijoada_%C3%A0_transmontada.jpg/500px-Feijoada_%C3%A0_transmontada.jpg"}]},{"i":"CH","dishes":[{"name":"Älplermagronen","desc":"Macaroni and diced potato boiled in the same pot, layered with melted mountain cheese and fried onion, and eaten with stewed apple on the side.","why":"Herders' food from the high summer pastures, using the four things a mountain hut kept: pasta, potato, cheese and cream.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/%C3%84lplermagronen_2021.jpeg/500px-%C3%84lplermagronen_2021.jpeg"},{"name":"Raclette","desc":"A half-wheel of cheese heated at the cut face and scraped molten onto boiled potatoes, eaten with pickled onions and gherkins.","why":"A Valais herders' supper; the name comes from the verb for scraping the melted face off the wheel.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Raclette_20040817_140816.jpg/500px-Raclette_20040817_140816.jpg"},{"name":"Rösti","desc":"Coarsely grated potato pressed into a pan and fried in butter until it sets into one solid golden cake, crisp on both sides.","why":"Originally a farmers' breakfast in Bern; the linguistic border between the German- and French-speaking halves is nicknamed the rosti ditch.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Roesti.jpg/500px-Roesti.jpg"},{"name":"Fondue","desc":"Two cheeses melted with white wine, garlic and a little starch in a communal pot kept warm over a flame, for dipping cubes of stale bread on long forks.","why":"Promoted hard by a cheese cartel in the 1930s and by the army, which is a large part of why it became a national symbol.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Fondue_dish.jpg/500px-Fondue_dish.jpg"}]},{"i":"CZ","dishes":[{"name":"Kulajda","desc":"A creamy dill and wild mushroom soup soured with vinegar, with diced potato and a poached egg floating in it.","why":"A Bohemian country soup; the combination of dill, sour cream and vinegar is the local flavour signature.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Kulajda_%281%29.jpg/500px-Kulajda_%281%29.jpg"},{"name":"Svíčková","desc":"Larded beef sirloin roasted and served in a smooth sauce of pureed root vegetables and cream, with sliced bread dumplings, cranberry and lemon.","why":"The Sunday dish, and the reason a whole genre of bread dumplings exists to mop up the sauce.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Sv%C3%AD%C4%8Dkov%C3%A1_na_smetan%C4%9B.JPG/500px-Sv%C3%AD%C4%8Dkov%C3%A1_na_smetan%C4%9B.JPG"},{"name":"Smažený sýr","desc":"A thick slab of semi-hard cheese breaded and deep-fried until it just starts to run, served with tartare sauce and chips.","why":"Communist-era pub food that never left; sold from hatches and eaten in a bread roll.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/SMAZENY_SYR_2020.jpg/500px-SMAZENY_SYR_2020.jpg"},{"name":"Vepřo knedlo zelo","desc":"Roast pork with slices of steamed bread dumpling cut off a log with thread, and stewed cabbage on the side.","why":"The three-word national dish -- pork, dumpling, cabbage -- and the standard measure of a pub kitchen.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Knedlo_vepro_zelo_czech_food.jpg/500px-Knedlo_vepro_zelo_czech_food.jpg"}]},{"i":"DE","dishes":[{"name":"Königsberger Klopse","desc":"Poached veal meatballs in a pale sauce sharpened with capers and lemon, served with boiled potatoes and beetroot.","why":"Named for a city that is now Kaliningrad; the East refused the name for decades and sold them as 'meatballs in caper sauce'.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Koenigsberger.jpg/500px-Koenigsberger.jpg"},{"name":"Maultaschen","desc":"Large pasta pockets stuffed with minced meat, spinach, breadcrumbs and onion, either floated in clear broth or sliced and fried.","why":"A Swabian speciality nicknamed 'God's little cheaters' -- monks are said to have hidden meat inside the pasta during Lent.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Maultaschensuppe.jpg/500px-Maultaschensuppe.jpg"},{"name":"Sauerbraten","desc":"Beef marinated for days in vinegar and spices, then braised and served in a sweet-sour gravy thickened with crushed spice biscuits and raisins.","why":"The Rhineland version uses gingerbread in the sauce; the long acid soak was originally a way of preserving the meat.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Heldrunger_Sauerbraten_2.JPG/500px-Heldrunger_Sauerbraten_2.JPG"},{"name":"Spätzle","desc":"Soft, irregular egg noodles scraped from a wet dough straight into boiling water, then tossed in butter and often layered with grated cheese and fried onion.","why":"The staple starch of Swabia, protected as a regional speciality, and traditionally scraped off a wooden board with a knife.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Sp%C3%A4tzle-02.jpg/500px-Sp%C3%A4tzle-02.jpg"},{"name":"Currywurst","desc":"A fried pork sausage cut into coins and buried under a spiced tomato sauce dusted with curry powder, eaten from a paper tray with a tiny fork.","why":"Invented in Berlin in 1949 by Herta Heuwer, who got the curry powder and ketchup from British soldiers.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/20220430_currywurst.jpg/500px-20220430_currywurst.jpg"}]},{"i":"DK","dishes":[{"name":"Stegt flæsk med persillesovs","desc":"Thick slices of pork belly fried until the fat crisps, served with boiled potatoes and a white sauce heavy with chopped parsley.","why":"Voted the national dish in a public poll in 2014, beating a long list of more elegant candidates.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/Stegt_fl%C3%A6sk.jpg/500px-Stegt_fl%C3%A6sk.jpg"},{"name":"Rødgrød med fløde","desc":"A pudding of red summer berries cooked with sugar and thickened with starch into a wobble, served cold under a pour of cream.","why":"Its name is the classic pronunciation test for foreigners -- a string of soft d's that almost nobody gets right.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Rote_Gr%C3%BCtze_mit_Vanilleso%C3%9Fe.JPG/500px-Rote_Gr%C3%BCtze_mit_Vanilleso%C3%9Fe.JPG"},{"name":"Frikadeller","desc":"Flat pan-fried patties of minced pork and veal bound with egg, flour, milk and grated onion, served with potatoes and pickled red cabbage.","why":"Weeknight food, shaped with a spoon rather than by hand, and eaten cold on rye bread the next day."},{"name":"Smørrebrød","desc":"A single slice of dense sour rye bread buttered and built up with cured fish or cold meat and an elaborate garnish, eaten with a knife and fork.","why":"An open sandwich with rules: there is a correct order to eat them in, and herring comes first.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Ida_Davidsen_udsnit_af_glasmontren.JPG/500px-Ida_Davidsen_udsnit_af_glasmontren.JPG"}]},{"i":"ES","dishes":[{"name":"Fabada","desc":"A heavy stew of large flat white beans with blood sausage, smoked paprika sausage and cured pork shoulder, simmered until the broth turns orange.","why":"Asturias in a pot: the beans are a specific local variety, and the three cured meats are known collectively as the compango.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Fabada_en_cazuela_de_barro.jpg/500px-Fabada_en_cazuela_de_barro.jpg"},{"name":"Salmorejo","desc":"A thick, cold, orange cream of raw tomato and bread emulsified with olive oil and garlic, topped with chopped boiled egg and cured ham.","why":"Cordoba's answer to the thinner cold soups of the same region -- more bread, more oil, thick enough to eat with a spoon.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Salmorejo_cordouan.JPG/500px-Salmorejo_cordouan.JPG"},{"name":"Pulpo a la gallega","desc":"Octopus boiled in a copper pot, snipped into coins over sliced potato and finished with coarse salt, sweet paprika and a flood of olive oil.","why":"Galicia's fair-day dish, cooked in copper by travelling pulpeiras and served on a wooden plate with a toothpick.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Polbo_a_feira.jpg/500px-Polbo_a_feira.jpg"},{"name":"Tortilla de patatas","desc":"A thick set omelette of egg with potato and onion poached soft in olive oil, flipped in the pan and cut into wedges, eaten warm or cold.","why":"The one dish in every bar in the country; whether onion belongs in it is a genuinely divisive national argument.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Tortilla_de_patata_-_San_Sebasti%C3%A1n.jpg/500px-Tortilla_de_patata_-_San_Sebasti%C3%A1n.jpg"},{"name":"Gazpacho","desc":"A cold raw soup of blended tomato, cucumber, pepper, garlic, bread, vinegar and olive oil, often drunk from a glass.","why":"Andalusian field food that predates tomatoes -- it was bread, oil, vinegar and garlic long before the New World arrived.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Gazpacho_Malague%C3%B1o_con_su_%E2%80%9Cpica%C3%ADto%E2%80%9D_-_Moreno%2C_Playa_Burriana_%28cropped%29.jpg/500px-Gazpacho_Malague%C3%B1o_con_su_%E2%80%9Cpica%C3%ADto%E2%80%9D_-_Moreno%2C_Playa_Burriana_%28cropped%29.jpg"},{"name":"Paella valenciana","desc":"Short-grain rice cooked flat and uncovered in a wide shallow pan with saffron, rabbit, chicken and flat green beans until a toasted crust forms underneath.","why":"A field lunch from the rice paddies around the Albufera lagoon; the crust stuck to the pan, the socarrat, is the prize.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/01_Paella_Valenciana_original.jpg/500px-01_Paella_Valenciana_original.jpg"}]},{"i":"ET","dishes":[{"name":"Shiro","desc":"A smooth stew of ground chickpea or broad-bean flour cooked with onion, garlic and a fiery red spice blend until it thickens like porridge.","why":"Fasting food for the Orthodox calendar's many meat-free days; the powder keeps for months, which is why it is everywhere.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Taita_and_shiro.jpg/330px-Taita_and_shiro.jpg"},{"name":"Kitfo","desc":"Raw minced beef warmed through in spiced clarified butter and chilli powder, served with a crumbly fresh cheese and cooked greens.","why":"A Gurage speciality; leb leb means barely warmed, and it is properly eaten with kocho, a bread made from the false-banana plant.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Kitfo_with_Ayibe..JPG/330px-Kitfo_with_Ayibe..JPG"},{"name":"Tibs","desc":"Cubes of beef or lamb seared fast with onion, rosemary, green chilli and spiced clarified butter, brought to the table still spitting in a clay dish.","why":"The celebration cut, often carved from an animal slaughtered that morning and cooked over a charcoal brazier set into the serving pot.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Person_Enjoys_Tibs.JPG/500px-Person_Enjoys_Tibs.JPG"},{"name":"Doro wat","desc":"Chicken stewed for hours with onions cooked dry until they collapse, a red chilli-and-spice blend and clarified butter, served with a whole hard-boiled egg.","why":"The feast dish for Christmas and Easter; the onions go in with no fat at all and can take an hour before anything else is added.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Ethiopian_wat.jpg/330px-Ethiopian_wat.jpg"},{"name":"Injera","desc":"A wide, soft, sour flatbread of fermented teff batter poured in a spiral onto a clay griddle, its top riddled with holes, used as plate, cutlery and food.","why":"Teff is a tiny indigenous grain; the batter ferments for days, which is where the sourness and the bubbles come from.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Injera_with_eight_kinds_of_stew.jpg/500px-Injera_with_eight_kinds_of_stew.jpg"}]},{"i":"FI","dishes":[{"name":"Kalakukko","desc":"Small freshwater fish and fatty pork sealed inside a rye loaf and baked for hours until the bones soften and the crust turns waterproof.","why":"A Savonian dish from around Kuopio with protected status; the sealed rye crust was the lunchbox before lunchboxes.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Kalakukko_%28opened%29.jpg/500px-Kalakukko_%28opened%29.jpg"},{"name":"Leipäjuusto","desc":"A squeaky fresh curd cheese pressed into a flat disc and grilled until it is brown-spotted, served warm with cloudberry jam.","why":"Northern 'bread cheese', once made with the first milk after a cow calved; it squeaks against the teeth."},{"name":"Karjalanpiirakka","desc":"An open oval pastry with a thin rye crust crimped around a filling of rice porridge, eaten spread with a mash of butter and chopped boiled egg.","why":"From Karelia, carried west by evacuees after the war; the butter-and-egg spread on top is munavoi.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Karjalanpiirakka-20060227.jpg/500px-Karjalanpiirakka-20060227.jpg"},{"name":"Salmiakki","desc":"A hard black sweet flavoured with ammonium chloride, tasting salty and sharply bitter rather than sugary.","why":"A national addiction that flavours everything from ice cream to vodka, and that almost no visitor enjoys on the first try.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Swedish_salty_liquorice.jpg/500px-Swedish_salty_liquorice.jpg"}]},{"i":"FR","dishes":[{"name":"Cassoulet","desc":"A slow-baked casserole of white beans with preserved duck leg, pork and garlic sausage, its browned crust broken back down into the pot as it cooks.","why":"Toulouse, Castelnaudary and Carcassonne each claim the original recipe; the crust is supposed to be pushed under seven times.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Bowl_of_cassoulet.JPG/500px-Bowl_of_cassoulet.JPG"},{"name":"Bouillabaisse","desc":"A fishermen's stew of several kinds of bony rockfish poached in a saffron and fennel broth, served with a rust-coloured garlic mayonnaise on toast.","why":"Marseille's harbour dish, built from the ugly rockfish nobody would buy; a 1980s charter set out which species may legitimately go in.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Bullabessa.jpg/500px-Bullabessa.jpg"},{"name":"Coq au vin","desc":"An old bird jointed and braised in red wine with salt pork, button mushrooms and small onions, the sauce finished with blood or liver.","why":"Burgundy's way with a bird too tough to roast; the long soak in wine is what makes it tender.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/Gourmet_coq_au_vin.jpg/500px-Gourmet_coq_au_vin.jpg"},{"name":"Ratatouille","desc":"Aubergine, courgette, sweet pepper, tomato and onion cooked separately in olive oil with thyme and bay, then brought together and stewed down.","why":"A Nicoise summer dish; cooking each vegetable apart is what stops it collapsing into a single mush.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Ratatouille_home_cooked.jpg/500px-Ratatouille_home_cooked.jpg"},{"name":"Tarte Tatin","desc":"An upside-down tart in which apples caramelise in butter and sugar under a pastry lid, then are turned out fruit-side up.","why":"Named for two sisters running a hotel near Orleans, who supposedly rescued a tart they had started to make the wrong way round.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Franse_tarte_tatin.jpg/500px-Franse_tarte_tatin.jpg"}]},{"i":"GB","dishes":[{"name":"Cullen skink","desc":"A thick soup of smoked haddock poached in milk with potato and onion, left chunky and eaten with bread.","why":"From the fishing town of Cullen on the Moray Firth; 'skink' is an old word for a shin-of-beef broth that the fishermen replaced with smoked fish.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Cullen_Skink.JPG/500px-Cullen_Skink.JPG"},{"name":"Toad in the hole","desc":"Sausages baked inside a loose egg-and-flour batter that puffs up and crisps around them, served with onion gravy.","why":"The batter is the same one that goes with a roast; the name has been in print since the 1700s and nobody has explained it convincingly.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Toad_in_the_hole.jpg/500px-Toad_in_the_hole.jpg"},{"name":"Welsh rarebit","desc":"A thick savoury sauce of sharp cheese melted with ale, mustard and Worcestershire sauce, poured over toast and grilled until it blisters.","why":"Not cheese on toast: the cheese is cooked into a mustardy sauce first, then browned under the grill.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Welsh_rarebit.JPG/500px-Welsh_rarebit.JPG"},{"name":"Sticky toffee pudding","desc":"A dark sponge made with chopped dates and treacle, drowned in hot toffee sauce and served with cream.","why":"A Lake District hotel invention of the 1970s that colonised every pub menu in the country within a decade.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Sticky_toffee_pudding_at_the_Black_Swan_-_Stierch.jpg/500px-Sticky_toffee_pudding_at_the_Black_Swan_-_Stierch.jpg"},{"name":"Cornish pasty","desc":"A hand-held pastry parcel crimped along one curved side, filled with raw beef skirt, potato, swede and onion that cook in their own steam.","why":"Legally protected: made in Cornwall, D-shaped, crimped at the side so a tin miner could hold it by the thick edge and throw that bit away.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Cornish_Pasty_%28cropped%29.jpeg/500px-Cornish_Pasty_%28cropped%29.jpeg"},{"name":"Shepherd's pie","desc":"Minced lamb stewed with onion, carrot and gravy under a thick mashed-potato lid, baked until the top is forked and browned.","why":"Lamb makes it a shepherd's pie, beef makes it a cottage pie -- both began as a way of using up Sunday's roast.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg/500px-Homerton_College_-_Shepherd%27s_pie_%28cropped%29.jpg"},{"name":"Fish and chips","desc":"White fish in a beer batter, deep-fried and served with thick-cut fried potatoes, mushy peas and malt vinegar.","why":"Sold from dedicated shops since the 1860s and never rationed during the Second World War, on the grounds that morale depended on it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Fish_and_chips_blackpool.jpg/500px-Fish_and_chips_blackpool.jpg"}]},{"i":"GE","dishes":[{"name":"Chakapuli","desc":"Lamb or veal stewed with masses of tarragon, unripe sour plums, spring onion and dry white wine until sharply sour and grassy.","why":"A spring dish, cooked in the few weeks when tarragon and sour plums are both available, often outdoors for Easter.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/PXL_20260504_183036483.MP.jpg/500px-PXL_20260504_183036483.MP.jpg"},{"name":"Pkhali","desc":"Chopped spinach, beetroot or beans pounded with ground walnuts, garlic, coriander and vinegar into cold pates, shaped into balls and dotted with pomegranate seeds.","why":"Served in a row of different colours at the start of a supra, the ritual feast run by a toastmaster.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Pkhali%2C_Badrijani_and_Ajika.jpg/500px-Pkhali%2C_Badrijani_and_Ajika.jpg"},{"name":"Satsivi","desc":"Poached chicken or turkey served cold under a thick, pale sauce of ground walnuts, garlic, coriander seed and dried marigold petals.","why":"The New Year dish; the yellow comes from dried marigold, used locally the way saffron is used elsewhere.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Satsivi_%282%29.jpg/500px-Satsivi_%282%29.jpg"},{"name":"Lobio","desc":"Kidney beans stewed with coriander, blue fenugreek and walnut and served in the clay pot they cooked in, with cornbread and pickles.","why":"Everyday food, and the reason the local blue fenugreek and dried marigold spice mix exists.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Lobio_with_summer_savory_and_ajika.jpg/500px-Lobio_with_summer_savory_and_ajika.jpg"},{"name":"Khinkali","desc":"Pleated dumplings with a twisted knot on top, filled with spiced minced meat and broth, boiled and eaten by hand -- the knot is left uneaten on the plate.","why":"Count the discarded knots to see who ate most; the soup inside comes from broth kneaded into the raw filling, not poured in.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Khinkali%2C_Restaurant_Aragvi.jpg/500px-Khinkali%2C_Restaurant_Aragvi.jpg"},{"name":"Khachapuri","desc":"A boat of yeasted dough filled with brined stretchy cheese, baked, then finished with a raw egg yolk and butter stirred into the molten middle.","why":"The Adjaran boat-shaped version from the Black Sea coast; inland versions are round and sealed, with the cheese hidden inside.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Old_Tbilisi%2C_Georgian_khachapuri%2C_Georgia.jpg/500px-Old_Tbilisi%2C_Georgian_khachapuri%2C_Georgia.jpg"}]},{"i":"GR","dishes":[{"name":"Fasolada","desc":"A soup-stew of white beans with carrot, celery and tomato and a very large quantity of olive oil, eaten with olives and bread.","why":"Often called the real national dish rather than the restaurant ones -- cheap, meatless and eaten through the Orthodox fasts.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Fasolada.JPG/500px-Fasolada.JPG"},{"name":"Pastitsio","desc":"Long tubular pasta layered with minced meat spiced with cinnamon and clove, under a thick baked white sauce.","why":"The cinnamon in the meat is the tell; it comes from the same Ottoman-era spicing as the aubergine bake it sits beside on every menu.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/Pastitsio_homemade.jpg/500px-Pastitsio_homemade.jpg"},{"name":"Spanakopita","desc":"Layers of paper-thin pastry brushed with oil around a filling of spinach, wild greens, dill and salty white cheese, baked in a tray and cut in squares.","why":"One of a whole family of savoury pies; the filling changes with whatever greens are growing on the hillside."},{"name":"Moussaka","desc":"Layers of fried aubergine and spiced minced lamb under a thick white sauce that puffs and browns in the oven.","why":"The custard-like top layer was added by Nikolaos Tselementes in the 1920s, which is why older versions elsewhere in the region have none.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/MussakasMeMelitsanesKePatates01.JPG/500px-MussakasMeMelitsanesKePatates01.JPG"},{"name":"Souvlaki","desc":"Small cubes of pork grilled on wooden skewers over coals and wrapped in flatbread with tomato, onion, chips and a thick garlic-yoghurt sauce.","why":"Skewered meat cooked exactly this way has been dug up here from the Bronze Age -- portable clay firedogs and all.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Souvlaki_in_Athens.JPG/500px-Souvlaki_in_Athens.JPG"}]},{"i":"HU","dishes":[{"name":"Halászlé","desc":"A fiery river-fish soup coloured deep red with sweet ground pepper, cooked in a kettle hung over an open fire.","why":"A fishermen's soup of the Danube and Tisza; Szeged strains it and Baja serves it over noodles, and the two do not agree.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Pot_of_Hungarian_Fisherman%27s_Soup_%28Hal%C3%A1szl%C3%A9%2C_Karpfensuppe%29.jpg/500px-Pot_of_Hungarian_Fisherman%27s_Soup_%28Hal%C3%A1szl%C3%A9%2C_Karpfensuppe%29.jpg"},{"name":"Lecsó","desc":"Sliced sweet yellow peppers and tomato cooked down slowly in lard with onion and ground red pepper, often with sausage or a beaten egg stirred in.","why":"Late-summer food made when the pepper glut arrives, and preserved in jars for winter.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/Warm_Colors-_my_Mom%27s_Hungarian_Lecs%C3%B3_cropped.jpg/500px-Warm_Colors-_my_Mom%27s_Hungarian_Lecs%C3%B3_cropped.jpg"},{"name":"Dobos torte","desc":"A cake of five thin sponge layers with chocolate buttercream, capped with a disc of hard caramel scored into wedges.","why":"Created by Jozsef Dobos in 1885; the caramel top was there to stop the cake drying out before refrigeration existed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Dobos_cake_%28Gerbeaud_Confectionery_Budapest_Hungary%29.jpg/500px-Dobos_cake_%28Gerbeaud_Confectionery_Budapest_Hungary%29.jpg"},{"name":"Gulyás","desc":"A soup of beef and potato in a thin broth loaded with sweet ground red pepper, caraway and onion, cooked in a kettle over a fire.","why":"A herdsmen's soup -- the word means 'cowherd' -- and abroad it got thickened into a stew it never was at home.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Gulyas080.jpg/500px-Gulyas080.jpg"}]},{"i":"IE","dishes":[{"name":"Coddle","desc":"Sausages and rashers of bacon layered with sliced potato and onion and simmered slowly in stock until everything is pale and soft.","why":"A Dublin dish built to use up whatever was left before the Friday fast; browning the meat first is considered cheating.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Irish_Coddle.jpg/500px-Irish_Coddle.jpg"},{"name":"Boxty","desc":"A potato pancake made with both grated raw and mashed cooked potato bound with flour and buttermilk, fried on a griddle.","why":"From the northern midlands, with its own rhyme: if you can't make boxty you will never get a man.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Boxty_triangle.jpg/500px-Boxty_triangle.jpg"},{"name":"Colcannon","desc":"Mashed potato beaten with butter and milk and shot through with finely shredded cooked kale or cabbage, with a well of melted butter in the middle.","why":"Eaten at Halloween with charms hidden inside -- a ring for marriage, a coin for wealth.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Colcannon.JPG/500px-Colcannon.JPG"},{"name":"Soda bread","desc":"A dense round loaf raised with bicarbonate of soda and buttermilk instead of yeast, scored with a deep cross before it goes into the oven.","why":"The soft local wheat will not make a good yeasted loaf, which is why chemical raising took hold here in the 1830s.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Ben_W_Bell_Soda_Bread_Farl_05_June_2007.jpg/500px-Ben_W_Bell_Soda_Bread_Farl_05_June_2007.jpg"},{"name":"Irish stew","desc":"Mutton or lamb on the bone layered with potato and onion and simmered in water until the top layer of potato breaks down and thickens it.","why":"Carrots and barley are late arrivals and still contested; the original was mutton, potato, onion and water, and nothing else.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Irish_Beef_Stew_%2834046928633%29.jpg/500px-Irish_Beef_Stew_%2834046928633%29.jpg"}]},{"i":"IN","dishes":[{"name":"Dhokla","desc":"A savoury steamed cake of fermented chickpea batter, spongy and faintly sour, tempered with mustard seed, curry leaf and green chilli.","why":"A Gujarati breakfast and tiffin staple; the batter ferments overnight before it is steamed in shallow trays and cut into diamonds.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Dhokla_on_Gujrart.jpg/500px-Dhokla_on_Gujrart.jpg"},{"name":"Rogan josh","desc":"Lamb braised in a brick-red gravy coloured by mild dried chillies and cockscomb flower, spiced with fennel and dried ginger and made without onion or garlic.","why":"A Kashmiri dish carried in by the Mughals; the colour comes from ratan jot and chilli, not from tomato.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Rogan_Josh_Kashmiri.jpg/500px-Rogan_Josh_Kashmiri.jpg"},{"name":"Pani puri","desc":"Hollow crisp spheres cracked open at the top, packed with potato and chickpea, flooded with iced mint-tamarind water and eaten whole in one bite.","why":"Street food with a dozen regional names -- golgappa, puchka, gup chup -- and a vendor who hands them over one at a time until you say stop.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Pani_Puri1.JPG/500px-Pani_Puri1.JPG"},{"name":"Idli","desc":"Soft steamed discs of fermented rice-and-lentil batter, faintly sour, eaten with a tamarind-lentil vegetable broth and coconut chutney.","why":"A southern breakfast; the fermentation is wild, driven by the lentil skins, and the batter is ground on stone.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Idli_Sambar.JPG/500px-Idli_Sambar.JPG"},{"name":"Masala dosa","desc":"An enormous thin crepe of fermented rice-and-lentil batter crisped on a griddle and folded around spiced turmeric-yellow potato.","why":"From Karnataka and now the country's most exported breakfast; the batter is the same as idli, ground finer and spread paper-thin.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/Rameshwaram_Cafe_Dosa.jpg/500px-Rameshwaram_Cafe_Dosa.jpg"},{"name":"Biryani","desc":"Long-grain rice layered raw over yoghurt-marinated meat and fried onions, sealed under a lid of dough and cooked so the grains steam in the meat's own vapour.","why":"The sealed-pot method arrived with Persian cooks; Hyderabad, Lucknow, Kolkata and Malabar each defend a different version.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/%22Hyderabadi_Dum_Biryani%22.jpg/500px-%22Hyderabadi_Dum_Biryani%22.jpg"},{"name":"Butter chicken","desc":"Clay-oven-charred chicken finished in a gravy of tomato, butter and cream scented with dried fenugreek leaf, mopped up with leavened flatbread.","why":"Invented in Delhi in the 1950s by cooks who needed something to do with yesterday's unsold tandoori chicken.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg/500px-Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg"}]},{"i":"IR","dishes":[{"name":"Halim","desc":"A thick breakfast porridge of wheat berries cooked down with shredded lamb or turkey and beaten for hours until it turns smooth and stringy, served under cinnamon, sugar and melted butter.","why":"A winter dawn food, ladled from vast copper vats before sunrise; the long beating is what pulls grain and meat into one ropy mass."},{"name":"Ash-e reshteh","desc":"A dense green soup of noodles, chickpeas, lentils and enormous quantities of herbs, finished with fried mint oil, caramelised onion and a swirl of sour whey.","why":"Cooked for Nowruz and for votive vows: the tangled noodles stand for the strands of fate you are asking to have untangled in the year ahead.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Ash_Reshteh.JPG/500px-Ash_Reshteh.JPG"},{"name":"Tahchin","desc":"A saffron-and-yoghurt rice cake pressed into a mould and baked until the base sets into a solid crimson crust, with shredded chicken or lamb hidden inside.","why":"The grandest form of tahdig, the crisp bottom-of-the-pot rice that gets fought over at every table.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Tachin.jpg/500px-Tachin.jpg"},{"name":"Faloodeh","desc":"Thin frozen starch noodles set in a rose water and sugar syrup, scraped icy into a bowl and eaten with lime juice or sour cherry syrup.","why":"Shiraz claims it, and it is one of the oldest frozen desserts anyone still eats -- described in texts well over a thousand years old.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Faloodeh1.jpg/500px-Faloodeh1.jpg"},{"name":"Sabzi polo ba mahi","desc":"Rice steamed with heaps of chopped dill, coriander, parsley, chives and fenugreek, served alongside a whole fish fried until the skin blisters.","why":"The meal of the spring equinox: green herbs for renewal, fish for life, eaten the moment the new year turns.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Sabzi_polo.jpg/500px-Sabzi_polo.jpg"},{"name":"Fesenjan","desc":"A dark, glossy braise of ground walnuts and pomegranate molasses cooked for hours with duck or chicken until the oil rises and the sauce turns almost black.","why":"A dish of the Caspian north and of the old royal kitchens; it must cook long enough for the walnut oil to separate out on top.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Khoresht-e_fesenjan.jpg/500px-Khoresht-e_fesenjan.jpg"},{"name":"Ghormeh sabzi","desc":"A deep green stew of parsley, coriander, fenugreek and leek fried until nearly black, then simmered with lamb, kidney beans and whole sun-dried limes.","why":"Widely called the national dish. The sourness is limoo omani -- limes dried whole in the sun, pierced before they go into the pot.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Ghormeh_Sabzi.JPG/500px-Ghormeh_Sabzi.JPG"},{"name":"Kabab koobideh","desc":"Minced lamb and beef kneaded with grated onion until sticky, pressed by hand onto wide flat skewers and grilled over charcoal with tomatoes.","why":"The everyday grill of every roadside restaurant; the meat is worked until it clings to the flat skewer and does not slide off over the coals.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Kabab_koobideh_bbq_persian_food.jpg/500px-Kabab_koobideh_bbq_persian_food.jpg"}]},{"i":"IS","dishes":[{"name":"Hákarl","desc":"Shark buried and pressed for weeks and then hung to dry for months until the ammonia in its flesh mellows, cut into cubes and eaten with a shot of caraway spirit.","why":"The shark is poisonous fresh -- it has no kidneys and excretes through its skin -- so fermenting it was the only way to eat it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Hakarl_near_Bjarnah%C3%B6fn_in_Iceland.JPG/500px-Hakarl_near_Bjarnah%C3%B6fn_in_Iceland.JPG"},{"name":"Plokkfiskur","desc":"Boiled white fish flaked into mashed potato with onion and a white sauce, browned in the oven and eaten with dark rye bread and butter.","why":"Leftovers food that became a canteen staple; the rye bread it is eaten with is steam-baked in the ground near hot springs."},{"name":"Skyr","desc":"A very thick, almost fat-free strained fresh cheese set with rennet and eaten like a yoghurt with milk and berries.","why":"Made here since settlement over a thousand years ago; technically a cheese, which is why it survived a dairy-free Viking sea voyage.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/De_Duitse_journaliste_Anita_Joachim_geniet_van_een_portie_skyr%2C_Bestanddeelnr_190-0483.jpg/500px-De_Duitse_journaliste_Anita_Joachim_geniet_van_een_portie_skyr%2C_Bestanddeelnr_190-0483.jpg"},{"name":"Pylsur","desc":"A hot dog of lamb, pork and beef in a small bun with both raw and crisp fried onion, ketchup, a sweet brown mustard and a creamy remoulade.","why":"The lamb is the giveaway; one stand in the capital has been selling them since 1937 and is the closest thing to a national restaurant."}]},{"i":"IT","dishes":[{"name":"Bagna cauda","desc":"A hot dip of anchovies and garlic melted into olive oil and butter, kept warm over a flame at the table for dunking raw and cooked vegetables.","why":"A Piedmontese autumn ritual eaten communally from one terracotta pot, traditionally after the grape harvest.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Bagna_Cauda_a_la_Champaqu%C3%AD_019.jpg/500px-Bagna_Cauda_a_la_Champaqu%C3%AD_019.jpg"},{"name":"Ribollita","desc":"A peasant soup of white beans, black cabbage and stale bread, boiled again the next day until it collapses into a thick spoonable mass.","why":"The name means 'reboiled': the bread is what turns yesterday's bean and cabbage soup into today's dinner.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Ribollita_Siena.jpg/500px-Ribollita_Siena.jpg"},{"name":"Ossobuco","desc":"Cross-cut veal shanks braised slowly in white wine and broth until the marrow softens, finished with a raw parsley, lemon zest and garlic gremolata.","why":"A Milanese dish, usually served on the saffron risotto from the same city; the hollow bone the name refers to is the point of it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Ossobuco.jpg/500px-Ossobuco.jpg"},{"name":"Risotto alla milanese","desc":"Short-grain rice toasted in butter and stirred with hot broth and saffron until it turns creamy, then beaten with grated hard cheese.","why":"Milan's yellow rice; the story ties it to a 16th-century glassworker who used saffron as a pigment for the cathedral windows.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg/500px-Risotto_with_speck_and_goat_cheese_%286101067436%29.jpg"},{"name":"Cacio e pepe","desc":"Pasta tossed with nothing but sheep's-milk cheese, cracked black pepper and starchy cooking water, worked into a glossy sauce.","why":"Shepherds' food from Lazio: three ingredients that travel well, and a sauce that splits into a lumpy mess if the pan is too hot.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Cacio_e_pepe.jpg/500px-Cacio_e_pepe.jpg"},{"name":"Tiramisu","desc":"Sponge fingers soaked in coffee, layered with whipped mascarpone and egg, dusted with cocoa and chilled.","why":"A surprisingly young dessert -- the evidence points to a restaurant in Treviso between the 1960s and 1970s.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Tiramisu_-_Raffaele_Diomede.jpg/500px-Tiramisu_-_Raffaele_Diomede.jpg"},{"name":"Pizza margherita","desc":"A thin wheat base blistered in seconds in a wood-fired oven under tomato, buffalo mozzarella and a few basil leaves.","why":"Named for Queen Margherita in 1889; the red, white and green were read as a nod to the flag of the newly unified kingdom.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Neapolitan_pizza_at_Trappica_%2848701940197%29.jpg/500px-Neapolitan_pizza_at_Trappica_%2848701940197%29.jpg"}]},{"i":"JP","dishes":[{"name":"Chawanmushi","desc":"A savoury egg custard steamed in a lidded cup with kelp-and-bonito stock, hiding prawn, mushroom and gingko nuts, and eaten with a spoon.","why":"One of very few dishes in this cuisine eaten with a spoon; steam it too hard and the custard goes porous instead of silky.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Chawan-mushi.JPG/500px-Chawan-mushi.JPG"},{"name":"Oden","desc":"Fish cakes, daikon, boiled eggs and konjac simmered for hours in a pale kelp-and-soy broth and ladled out compartment by compartment.","why":"Winter convenience-store food, kept bubbling in a divided tray beside the till from October onwards.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Yataioden.jpg/500px-Yataioden.jpg"},{"name":"Okonomiyaki","desc":"A thick cabbage-packed batter pancake griddled with pork belly, then painted with sweet brown sauce and mayonnaise and topped with dried fish flakes that curl in the heat.","why":"The name means 'grill what you like'. Osaka mixes everything into the batter; Hiroshima layers it and slips fried noodles underneath.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Okonomiyaki_001.jpg/500px-Okonomiyaki_001.jpg"},{"name":"Tonkatsu","desc":"A pork loin cutlet coated in coarse dry breadcrumbs, deep-fried, sliced into strips and served with shredded raw cabbage and a fruity brown sauce.","why":"A late-19th-century western import naturalised so thoroughly that the sauce, the cabbage and the rice alongside are now fixed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg/500px-%22Amai-Yuwaku%22_Special_Loin_Pork_Cutlet1.jpg"},{"name":"Ramen","desc":"Alkaline wheat noodles in a long-boiled pork-bone or soy broth, topped with rolled braised pork belly, a marinated soft-yolk egg and spring onion.","why":"Chinese in origin, remade region by region -- pork-bone in Fukuoka, miso in Sapporo, soy in Tokyo.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg/500px-Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg"},{"name":"Sushi","desc":"Vinegared short-grain rice pressed by hand into small blocks and draped with raw fish, or rolled with it inside a sheet of dried seaweed.","why":"Began as a fast street food in 19th-century Edo, when the fermented original was replaced by rice seasoned with vinegar.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Sushi_platter.jpg/500px-Sushi_platter.jpg"}]},{"i":"KR","dishes":[{"name":"Samgyetang","desc":"A whole young chicken stuffed with sticky rice, ginseng root, garlic and jujube, boiled until the broth turns milky, and eaten scalding hot in midsummer.","why":"Eaten on the three hottest days of the year, on the principle of fighting heat with heat.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Samgye-tang_2.jpg/500px-Samgye-tang_2.jpg"},{"name":"Sundubu jjigae","desc":"A furiously bubbling red stew of soft unpressed curdled soybean with fermented chilli paste, seafood or pork, and a raw egg cracked in at the table.","why":"Served in a stone pot straight off the flame; the curd is so soft it is spooned in rather than cut.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/02/Sundubu-jjigae.jpg/500px-Sundubu-jjigae.jpg"},{"name":"Japchae","desc":"Chewy translucent sweet-potato starch noodles tossed in sesame oil and soy with separately fried vegetables and thin strips of beef, served warm or cool.","why":"A royal court dish from the 17th century that had no noodles in it at all until the 20th.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Polish_Korean_Cuisine_and_Culture_Exchanges_Gradmother%E2%80%99s_Recipes_05.jpg/500px-Polish_Korean_Cuisine_and_Culture_Exchanges_Gradmother%E2%80%99s_Recipes_05.jpg"},{"name":"Tteokbokki","desc":"Chewy cylinders of pounded rice cake simmered in a sweet-hot fermented chilli sauce with fish cake, boiled egg and spring onion.","why":"Street-stall food since the 1950s, when wheat aid and a fiery gochujang sauce turned a mild court dish red.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Tteokbokki.JPG/500px-Tteokbokki.JPG"},{"name":"Bibimbap","desc":"A bowl of rice topped with separate mounds of seasoned vegetables, minced beef and a fried egg, stirred together with fermented chilli paste before eating.","why":"Jeonju's version is the famous one; the stone-bowl variant keeps sizzling so a crust forms on the bottom.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Dolsot-bibimbap.jpg/500px-Dolsot-bibimbap.jpg"},{"name":"Kimchi","desc":"Cabbage salted overnight, then coated in a paste of chilli powder, garlic, ginger and salted shrimp and left to ferment until sour and fizzing.","why":"Made communally in late autumn and buried in jars; there are hundreds of regional and seasonal versions besides the cabbage one.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Various_kimchi.jpg/500px-Various_kimchi.jpg"}]},{"i":"LB","dishes":[{"name":"Shish barak","desc":"Small meat dumplings simmered in warm garlicky yoghurt stabilised so it does not split, finished with fried pine nuts and dried mint.","why":"A winter dish of the mountain villages; the yoghurt is cooked with starch and stirred one way only, or it curdles.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/D%C3%BC%C5%9Fb%C9%99r%C9%99_yar%C4%B1mfabrikat%C4%B1_1.jpg/330px-D%C3%BC%C5%9Fb%C9%99r%C9%99_yar%C4%B1mfabrikat%C4%B1_1.jpg"},{"name":"Kibbeh nayyeh","desc":"Very lean raw lamb pounded with fine cracked wheat, grated onion and spices, spread flat on a plate and eaten with olive oil, mint and flatbread.","why":"The Sunday-lunch centrepiece of the mountains, pounded in a stone mortar; the cooked version is shaped into torpedoes and deep-fried.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/88/Kibbeh3.jpg/500px-Kibbeh3.jpg"},{"name":"Mujaddara","desc":"Lentils and rice cooked together and buried under onions fried to the edge of burnt, eaten warm or cold with yoghurt.","why":"Medieval cookbooks record it as the food of the poor; the whole flavour comes from how far you dare take the onions.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c9/Mujaddara.jpg/330px-Mujaddara.jpg"},{"name":"Manakish","desc":"Flatbread baked with a paste of dried wild thyme, sesame and sour red sumac loosened with olive oil, eaten hot for breakfast.","why":"Taken to the neighbourhood oven on a tray in the morning; the herb blend is za'atar, mixed differently by every household.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/Zaatar_Mankousheh.jpg/500px-Zaatar_Mankousheh.jpg"},{"name":"Fattoush","desc":"A salad of tomato, cucumber, radish, purslane and herbs tossed with torn toasted flatbread and dressed with lemon, olive oil and sour red sumac.","why":"A peasant salad built to use up stale bread, and one of the two that anchor a mezze table.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Fattoush_mixed-salad.jpg/330px-Fattoush_mixed-salad.jpg"},{"name":"Tabbouleh","desc":"A salad that is overwhelmingly finely chopped parsley and mint with only a little soaked cracked wheat, plus tomato, lemon and olive oil.","why":"Here it is a herb salad with a hint of grain -- the reverse of the grain salads sold under the name abroad.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Tabouleh_1.JPG/330px-Tabouleh_1.JPG"}]},{"i":"MX","dishes":[{"name":"Cochinita pibil","desc":"Pork marinated in sour orange juice and ground annatto seed, wrapped in banana leaves and roasted for hours in a covered earth pit until it shreds, served with pickled red onion.","why":"A Yucatan pit-roast: pib is the earth oven, and the orange-red colour is achiote seed rather than chilli.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Cochinita_pibil_2.jpg/500px-Cochinita_pibil_2.jpg"},{"name":"Chiles en nogada","desc":"Roasted green peppers stuffed with a sweet-savoury minced meat and fruit filling, cloaked in a cold walnut cream and scattered with pomegranate seeds and parsley.","why":"Green, white and red -- the national colours -- and eaten in the weeks around independence in September, when walnuts and pomegranates are both in.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Chile_en_nogada24.jpg/500px-Chile_en_nogada24.jpg"},{"name":"Mole poblano","desc":"A near-black sauce of several kinds of dried chilli with nuts, seeds, spices, stale bread and a little chocolate, all toasted, ground and fried before the broth goes in, served over turkey.","why":"Puebla's convent sauce, with more than twenty ingredients, each toasted separately; chocolate is a seasoning here, not a sweetener.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/ChickRedMole.JPG/500px-ChickRedMole.JPG"},{"name":"Pozole","desc":"A soup of dried field corn treated with lime until the kernels bloom open, simmered with pork and dressed at the table with shredded cabbage, radish, oregano and lime.","why":"A weekend and holiday soup that comes in red, white or green depending on the region; the bloomed corn is the whole point.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Green_pozole%2C_dressed_%2829161841908%29_%28cropped%29.jpg/500px-Green_pozole%2C_dressed_%2829161841908%29_%28cropped%29.jpg"},{"name":"Tamales","desc":"Corn dough beaten with fat until it floats, spread on a soaked husk around a chilli-braised filling, folded and steamed until it sets.","why":"Pre-Columbian and made everywhere from Sonora to Oaxaca; families steam hundreds at a time for Candlemas on 2 February.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Tamale_Oaxaque%C3%B1o.jpg/500px-Tamale_Oaxaque%C3%B1o.jpg"},{"name":"Tacos al pastor","desc":"Pork marinated in dried chilli and annatto, stacked on a vertical spit under a pineapple, shaved onto small maize tortillas with onion and coriander.","why":"Lebanese immigrants brought the vertical shawarma spit in the early 20th century; the lamb became pork and the pineapple stayed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Tacos-al-Pastor.jpg/500px-Tacos-al-Pastor.jpg"}]},{"i":"NG","dishes":[{"name":"Ogbono soup","desc":"A deliberately slippery, drawing soup thickened with ground wild-mango kernels, cooked with red palm oil, meat, dried fish and leafy greens.","why":"The texture is the point: it should pull into long threads off the spoon, which is what tells you the kernels were ground fresh.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/Ogbono_soup_with_assorted_meats.jpg/500px-Ogbono_soup_with_assorted_meats.jpg"},{"name":"Moin moin","desc":"A savoury steamed pudding of blended peeled beans with peppers, onion and oil, set in leaf wraps or tins, often with boiled egg or fish buried inside.","why":"The skins have to be rubbed off the beans by hand before blending, which is why it is party food rather than weeknight food.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Moin-Moin-good.jpg/500px-Moin-Moin-good.jpg"},{"name":"Pepper soup","desc":"A thin, ferociously hot broth of goat, catfish or offal scented with a blend of aromatic bark and seeds, drunk from a bowl.","why":"Ordered at bars and after childbirth alike; the spice blend leans on grains of selim and calabash nutmeg rather than chilli alone.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Assorted_meat_pepper_soup_at_Lagos_Island.jpg/500px-Assorted_meat_pepper_soup_at_Lagos_Island.jpg"},{"name":"Egusi soup","desc":"A thick stew of ground melon seeds that set into soft curds as they cook, with red palm oil, bitter leaf or spinach, and assorted meat and fish.","why":"Eaten with a 'swallow' -- pounded yam or cassava fufu, pinched into a ball, dipped and swallowed without chewing.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/EGUSI.JPG/500px-EGUSI.JPG"},{"name":"Suya","desc":"Thin strips of beef rubbed with a dry blend of ground peanut, chilli, ginger and spices, grilled over wood and served with raw onion and more of the spice mix.","why":"A Hausa grill from the north, sold from smoky roadside stands after dark and wrapped in newspaper.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/SuyavarietiesTX.JPG/500px-SuyavarietiesTX.JPG"},{"name":"Jollof rice","desc":"Long-grain rice cooked in a blended stew of tomato, red pepper, onion and spices until every grain is orange and the bottom of the pot catches.","why":"The centre of a long-running rivalry with Ghana and Senegal; cooked over firewood at parties so the smoke gets into it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Jollof_Rice_with_Stew.jpg/500px-Jollof_Rice_with_Stew.jpg"}]},{"i":"NL","dishes":[{"name":"Haring","desc":"Raw young herring cured briefly in light brine, served with chopped raw onion and pickles and eaten from a stall by holding it up by the tail.","why":"The first barrel of the new season's catch is auctioned for charity; the enzymes in the fish's own pancreas do the curing.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Haring_04.jpg/500px-Haring_04.jpg"},{"name":"Stamppot","desc":"Potatoes mashed together with kale, endive or sauerkraut and served with a smoked sausage laid on top and a well of gravy in the middle.","why":"Winter food, and the reason a specific curly kale variety is grown here; it is supposed to be picked after the first frost.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Boerenkool_stamppot.jpg/500px-Boerenkool_stamppot.jpg"},{"name":"Bitterballen","desc":"Crumbed, deep-fried spheres of a chilled beef ragout that turn molten inside, eaten with mustard alongside a beer.","why":"The standard bar snack, served in a basket with a small bowl of mustard; biting one straight from the fryer is a rite of passage.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Bitterballen_mosterd_mayo.jpg/500px-Bitterballen_mosterd_mayo.jpg"},{"name":"Stroopwafel","desc":"Two wafer-thin waffle discs sliced apart and glued back together with a caramel syrup, meant to be warmed over the mouth of a hot drink.","why":"Invented in Gouda around 1800 from bakery offcuts and syrup; the market version is cut from a hot iron and filled while still soft.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Stroopwafels_01.jpg/500px-Stroopwafels_01.jpg"}]},{"i":"NO","dishes":[{"name":"Lutefisk","desc":"Dried whitefish soaked in lye until it swells into a translucent jelly, then rinsed for days, baked and served with bacon, peas and potato.","why":"A Christmas dish of the Lutheran west coast; the lye has to be washed out completely or the fish is inedible.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/62/ForkLutefisk.jpg/500px-ForkLutefisk.jpg"},{"name":"Lefse","desc":"A soft, very thin potato flatbread cooked on a dry griddle and rolled up with butter, sugar and cinnamon.","why":"Rolled with a grooved pin and turned with a flat stick; every valley has its own thickness and sweetening.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Lefse_on_a_griddle.jpg/500px-Lefse_on_a_griddle.jpg"},{"name":"Fårikål","desc":"Mutton on the bone layered with whole wedges of cabbage and black peppercorns and simmered for hours with almost nothing else.","why":"Has its own national day on the last Thursday in September, and four ingredients that a 1970s campaign tried and failed to change.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/F%C3%A5r_i_k%C3%A5l.jpg/500px-F%C3%A5r_i_k%C3%A5l.jpg"},{"name":"Brunost","desc":"A caramel-brown cheese made by boiling whey down until the milk sugars caramelise, sliced paper-thin with a plane onto bread or waffles.","why":"Not really a cheese at all but concentrated whey; a lorry-load of it once burned for four days inside a tunnel.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Brunost.jpg/500px-Brunost.jpg"}]},{"i":"PE","dishes":[{"name":"Papa a la huancaina","desc":"Slices of boiled potato under a smooth cold sauce of fresh cheese, milk, crackers and yellow chilli, garnished with black olives and boiled egg.","why":"Named for Huancayo and said to have been invented for railway workers; the yellow chilli is aji amarillo, the backbone of the whole cuisine.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Papa_a_la_huancaina.jpg/500px-Papa_a_la_huancaina.jpg"},{"name":"Causa","desc":"Cold mashed yellow potato whipped with lime juice and yellow chilli paste, layered like a terrine with chicken or crab salad and avocado, and served chilled.","why":"Built on the yellow potato of the highlands -- one of thousands of native varieties -- and eaten cold, in neat layers, like a savoury cake.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Causa_Rellena.jpg/500px-Causa_Rellena.jpg"},{"name":"Aji de gallina","desc":"Shredded hen in a thick sauce of yellow chilli, bread soaked in milk, walnuts and cheese, spooned over boiled potato and white rice.","why":"A colonial adaptation of a medieval almond-and-bread dish, rebuilt around the local yellow chilli.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Aj%C3%AD_de_gallina.jpg/500px-Aj%C3%AD_de_gallina.jpg"},{"name":"Anticuchos","desc":"Marinated beef hearts threaded onto skewers and grilled hard over coals with dried red chilli, cumin, garlic and vinegar.","why":"Offal cuts given to enslaved and indentured workers in the colonial era, now the smell of every evening street corner.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Anticuchos_-_Grilled_Beef_Heart_skewers.jpg/500px-Anticuchos_-_Grilled_Beef_Heart_skewers.jpg"},{"name":"Lomo saltado","desc":"Strips of beef seared in a scorching wok with red onion, tomato and soy sauce, tossed with fried potatoes and served with rice.","why":"Chifa cooking: Cantonese wok technique brought by 19th-century migrants, applied to beef, potatoes and soy all on one plate.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg/500px-Lomo_Saltado_-_Lima%2C_Peru_Miraflores_%28Tiendecita_Blanca%29.jpg"},{"name":"Ceviche","desc":"Raw white fish cured in minutes in lime juice with red onion, chilli and coriander, served with sweet potato and large-kernel boiled corn.","why":"Declared national cultural heritage; the milky lime marinade left in the bowl is drunk separately as leche de tigre.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Cebiche_de_corvina.JPG/500px-Cebiche_de_corvina.JPG"}]},{"i":"PL","dishes":[{"name":"Żurek","desc":"A sour soup based on a fermented rye-flour starter, with white sausage, boiled egg and marjoram, sometimes served inside a hollowed loaf.","why":"The Easter breakfast soup; the sour starter is left to ferment for days and sold in bottles in every shop before the holiday."},{"name":"Bigos","desc":"Sauerkraut and fresh cabbage stewed for days with several meats, dried wild mushrooms and prunes, improving each time it is cooled and reheated.","why":"The hunter's stew of the old nobility, taken on hunts in a barrel and reheated over a fire; it is supposed to be better on day three.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Bigos_%281%29.jpg/500px-Bigos_%281%29.jpg"},{"name":"Gołąbki","desc":"Blanched cabbage leaves rolled around minced meat and rice into parcels and baked under a tomato or mushroom sauce.","why":"The name means 'little pigeons', and the parcels turn up right across the region -- but this is where they are a Sunday centrepiece.","img":"https://www.themealdb.com/images/media/meals/z267f71764364072.jpg"},{"name":"Pierogi","desc":"Half-moon dumplings of soft dough filled with curd cheese and potato, or mushroom and sauerkraut, boiled and then fried in butter with onion.","why":"The cheese-and-potato filling is called ruskie, which refers to a historic region and not to Russia.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Pierogi_z_mas%C5%82em_-_2023.03.31.jpg/500px-Pierogi_z_mas%C5%82em_-_2023.03.31.jpg"}]},{"i":"PT","dishes":[{"name":"Bacalhau à Brás","desc":"Salt cod soaked back to life and shredded, tossed with matchstick fried potatoes and softened onion, then bound with beaten egg and scattered with black olives.","why":"One of a claimed several hundred ways with salt cod, the fish this country has been drying and trading since the age of the cod banks.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Bacalhau_a_Bras.jpg/500px-Bacalhau_a_Bras.jpg"},{"name":"Francesinha","desc":"A sandwich stacked with steak, sausage and ham, blanketed in melted cheese and flooded with a hot beer-and-tomato sauce, with a fried egg and chips.","why":"Invented in Porto in the 1950s by a returning emigrant trying to rebuild the croque-monsieur he had eaten in France.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Francesinha_Sandwich_%28cropped%29.jpg/500px-Francesinha_Sandwich_%28cropped%29.jpg"},{"name":"Caldo verde","desc":"A soup of pureed potato and onion carrying paper-thin shreds of dark green cabbage and a slice of smoked sausage, finished with olive oil.","why":"From the Minho in the north and served at every festival and wedding; the cabbage is sliced so finely it is almost thread.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Caldo_verde.jpg/500px-Caldo_verde.jpg"},{"name":"Pastel de nata","desc":"A small cup of shatteringly flaky laminated pastry filled with cinnamon-scented egg custard and blistered black on top in a ferociously hot oven.","why":"Made by monks at the Jeronimos monastery in Belem before 1834, using the egg yolks left over from starching habits with the whites.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Pasteis_de_Belem.jpg/500px-Pasteis_de_Belem.jpg"}]},{"i":"SE","dishes":[{"name":"Surströmming","desc":"Baltic herring fermented in the tin until the can bulges, opened outdoors and eaten in thin flatbread with almond potato and onion.","why":"Fermented since at least the 16th century as a way of preserving fish with very little salt, which was expensive and taxed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Surstr%C3%B6mming.jpg/500px-Surstr%C3%B6mming.jpg"},{"name":"Toast Skagen","desc":"Chopped prawns folded through mayonnaise, dill and a little mustard, piled on fried bread and topped with roe.","why":"Invented by restaurateur Tore Wretman in the 1950s and named after a Danish fishing port, which has never stopped anyone claiming it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Toast_skagen_med_l%C3%B6jrom_och_citron%2C_November_2023.jpg/500px-Toast_skagen_med_l%C3%B6jrom_och_citron%2C_November_2023.jpg"},{"name":"Gravlax","desc":"Salmon buried for a couple of days in salt, sugar and dill, then sliced thin and served with a sweet mustard-and-dill sauce.","why":"The name means 'buried salmon' -- it really was buried in the sand above the tideline to ferment before curing replaced that.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Laxr%C3%A4tter.jpg/500px-Laxr%C3%A4tter.jpg"},{"name":"Köttbullar","desc":"Small meatballs of minced pork and beef bound with milk-soaked breadcrumb and grated onion, fried and served with cream gravy, potatoes and a tart red berry jam.","why":"King Charles XII is credited with bringing the idea back from Constantinople in the 18th century; the lingonberry is non-negotiable."}]},{"i":"TH","dishes":[{"name":"Khao soi","desc":"A curried coconut noodle soup crowned with a nest of deep-fried crisp egg noodles, served with pickled mustard greens, shallot and lime alongside.","why":"The noodle bowl of Chiang Mai and the north, carried down the old caravan routes from Yunnan by Muslim traders.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg/500px-Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg"},{"name":"Massaman curry","desc":"A mild, fragrant curry of beef or chicken with potato and peanuts, scented with cardamom, cinnamon, clove and star anise in coconut milk.","why":"A Muslim-influenced southern curry whose warm dry spices arrived by sea with Persian and Indian traders in the 17th century.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Kaeng_matsaman_kai.JPG/500px-Kaeng_matsaman_kai.JPG"},{"name":"Som tam","desc":"Shredded unripe papaya bruised in a tall clay mortar with garlic, chillies, lime, fish sauce, palm sugar, tomato and long beans.","why":"Isan food from the north-east, eaten with sticky rice; vendors are recognised by the rhythm of the pestle.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/2013_Tam_Lao.jpg/500px-2013_Tam_Lao.jpg"},{"name":"Tom yum goong","desc":"A clear, fiery-sour prawn soup sharpened with lemongrass, galangal, makrut lime leaf, bird's eye chilli and lime juice.","why":"The sourness is lime and the heat is fresh chilli -- no vinegar and no sweetness; the creamy version adds evaporated milk.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/Tom_yam_kung_maenam.jpg/500px-Tom_yam_kung_maenam.jpg"},{"name":"Mango sticky rice","desc":"Glutinous rice steamed and soaked in sweetened coconut cream, served with slices of ripe mango and a salted coconut drizzle.","why":"A hot-season dessert tied to the April mango harvest, sold from carts with the rice kept warm under cloth.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Mango_sticy_rice_%283859549574%29.jpg/500px-Mango_sticy_rice_%283859549574%29.jpg"},{"name":"Pad thai","desc":"Thin rice noodles stir-fried hard with tamarind, fish sauce and palm sugar, with egg, prawns, pressed tofu, bean sprouts and garlic chives, finished with crushed peanuts.","why":"Promoted by the government in the 1930s and 40s as a national noodle dish, to cut wheat imports and forge a modern identity.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg/500px-Phat_Thai_kung_Chang_Khien_street_stall.jpg"}]},{"i":"TR","dishes":[{"name":"Manti","desc":"Minute hand-pinched dumplings of spiced minced lamb, boiled and served under garlic yoghurt and butter reddened with pepper flakes and dried mint.","why":"Kayseri's version is the prestige one -- folded so small that forty are supposed to fit on a single spoon.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Kayseride_bir_restoranda_Kayseri_mant%C4%B1s%C4%B1_%28cropped%29.jpg/500px-Kayseride_bir_restoranda_Kayseri_mant%C4%B1s%C4%B1_%28cropped%29.jpg"},{"name":"Menemen","desc":"Eggs stirred loosely into softened green peppers and tomato with plenty of oil and left runny, scooped straight from the pan with bread.","why":"The breakfast standard; the argument is whether onion belongs in it, and the answer depends on which coast you are from.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Menemen_in_a_sahan.jpg/330px-Menemen_in_a_sahan.jpg"},{"name":"Pide","desc":"A long boat-shaped flatbread baked with minced meat, cheese or egg inside, its edges folded up to hold the filling in.","why":"Baked in a stone oven and cut across into strips; the Black Sea version closes over cheese and butter and gets an egg on top.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Pide_%28meal%29.jpg/500px-Pide_%28meal%29.jpg"},{"name":"Iskender kebab","desc":"Sliced spit-roasted lamb laid over cubes of flatbread, doused in hot tomato sauce and foaming melted butter, with thick yoghurt on the side.","why":"Named after the Bursa butcher who, in the 1860s, turned the horizontal kebab spit upright -- the ancestor of every doner since.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/%C4%B0skender_Kebap.jpg/500px-%C4%B0skender_Kebap.jpg"},{"name":"Lahmacun","desc":"A paper-thin round of dough spread with minced lamb, tomato, pepper and parsley, baked for barely two minutes, then squeezed with lemon and rolled around salad.","why":"A south-eastern speciality from around Gaziantep and Sanliurfa, sold by bakeries by the piece.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Lahmacun.jpg/330px-Lahmacun.jpg"},{"name":"Baklava","desc":"Dozens of sheets of stretched pastry brushed with clarified butter, packed with ground pistachios and soaked in sugar syrup the moment it leaves the oven.","why":"Shared across the whole former Ottoman world, but Gaziantep's pistachio version carries a protected designation; the dough is stretched until you can read through it.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c7/Baklava%281%29.png/500px-Baklava%281%29.png"}]},{"i":"VN","dishes":[{"name":"Cao lau","desc":"Thick chewy noodles said to require water from one particular well, served with slices of roast pork, crisp fried croutons, herbs and barely any broth.","why":"Made only in Hoi An; the noodles are treated with lye water from the ash of a specific island's wood.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg/500px-Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg"},{"name":"Bun cha","desc":"Charcoal-grilled pork patties and belly slices floating in a sweet-sour fish-sauce broth, with cold rice vermicelli and a basket of raw herbs to dip.","why":"Hanoi's lunch, eaten on plastic stools in the smoke of the grill -- and the meal Obama and Anthony Bourdain shared in 2016.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg/500px-B%C3%BAn_ch%E1%BA%A3_Vietnamese_food.jpg"},{"name":"Banh xeo","desc":"A large crisp turmeric-yellow rice-flour crepe folded over pork, prawns and bean sprouts, then torn up and wrapped in lettuce and herbs before dipping.","why":"The name means 'sizzling cake', after the noise the batter makes hitting the hot pan; the south makes them huge, the centre makes them small.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Banh_Xeo_with_fish_sauce_and_vegetables.jpg/500px-Banh_Xeo_with_fish_sauce_and_vegetables.jpg"},{"name":"Banh mi","desc":"A light, crackly rice-and-wheat baguette split and filled with pate, cold pork, pickled carrot and daikon, coriander, chilli and mayonnaise.","why":"A colonial French loaf lightened with rice flour and refilled with local pickles and herbs -- the empire's bread, comprehensively repurposed.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png/500px-B%C3%A1nh_m%C3%AC_th%E1%BB%8Bt_n%C6%B0%E1%BB%9Bng.png"},{"name":"Pho","desc":"A clear beef broth simmered for hours with charred ginger and onion, star anise and cinnamon, poured boiling over flat rice noodles and raw sliced beef.","why":"Born in the north around Hanoi in the early 20th century and carried south, then worldwide, by two waves of migration.","img":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Bowl_of_Meatball_pho.jpg/500px-Bowl_of_Meatball_pho.jpg"}]}],"byRegion":{"Africa":["ET","NG"],"Americas":["BR","MX","PE"],"Asia":["GE","IN","IR","JP","KR","LB","TH","TR","VN"],"Europe":["AT","BE","CH","CZ","DE","DK","ES","FI","FR","GB","GR","HU","IE","IS","IT","NL","NO","PL","PT","SE"]},"sources":["TheMealDB v1 public API (themealdb.com) -- dish photographs","Wikipedia REST summary lead images on upload.wikimedia.org (Wikimedia Commons, CC BY-SA / public domain)","Dish names, descriptions and notes authored for this build (_build/food_authored.py)"]};
